import { useMemo, useRef } from 'react';
import { useLanguageServiceContext } from '@/context/LanguageServiceContext';
import { useScripts } from '@/context/ScriptsContext';
import Highlighted from './Highlighted';

type KB = React.KeyboardEvent<HTMLTextAreaElement>;

const LINE_HEIGHT = 22;
const PAD_Y = 14;

function insert(textarea: HTMLTextAreaElement, value: string, setText: (v: string) => void) {
  textarea.focus();
  // execCommand keeps the browser's undo history; fall back to a manual splice.
  if (!document.execCommand('insertText', false, value)) {
    const { selectionStart: start, selectionEnd: end, value: text } = textarea;
    setText(text.slice(0, start) + value + text.slice(end));
    requestAnimationFrame(() => {
      textarea.selectionStart = textarea.selectionEnd = start + value.length;
    });
  }
}

export default function CodeEditor() {
  const { text, setText, tokens, compile, error } = useLanguageServiceContext();
  const { save } = useScripts();
  const highlightRef = useRef<HTMLPreElement | null>(null);
  const gutterRef = useRef<HTMLDivElement | null>(null);
  const escapedRef = useRef(false);

  const lineCount = useMemo(() => text.split('\n').length, [text]);
  const errorLine = error?.line ?? null;

  const onKeyDown = (e: KB) => {
    const textarea = e.currentTarget;
    const mod = e.metaKey || e.ctrlKey;
    if (mod && e.key === 'Enter') {
      e.preventDefault();
      compile();
      return;
    }
    if (mod && e.key.toLowerCase() === 's') {
      e.preventDefault();
      save();
      return;
    }
    if (e.key === 'Escape') {
      escapedRef.current = true; // the next Tab leaves the editor
      return;
    }
    if (e.key === 'Tab') {
      if (escapedRef.current) {
        escapedRef.current = false;
        return;
      }
      e.preventDefault();
      const { selectionStart: start, value } = textarea;
      if (e.shiftKey) {
        const lineStart = value.lastIndexOf('\n', start - 1) + 1;
        if (value[lineStart] === '\t') {
          textarea.setSelectionRange(lineStart, lineStart + 1);
          insert(textarea, '', setText);
          const caret = Math.max(lineStart, start - 1);
          textarea.setSelectionRange(caret, caret);
        }
      } else {
        insert(textarea, '\t', setText);
      }
      return;
    }
    escapedRef.current = false;
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      const { selectionStart: start, value } = textarea;
      const lineStart = value.lastIndexOf('\n', start - 1) + 1;
      const line = value.slice(lineStart, start);
      const indent = line.match(/^\t*/)?.[0] ?? '';
      const opensBlock = line.trimEnd().endsWith(':');
      insert(textarea, `\n${indent}${opensBlock ? '\t' : ''}`, setText);
    }
  };

  const onScroll = (e: React.UIEvent<HTMLTextAreaElement>) => {
    const { scrollTop, scrollLeft } = e.currentTarget;
    if (highlightRef.current) {
      highlightRef.current.style.transform = `translate(${-scrollLeft}px, ${-scrollTop}px)`;
    }
    if (gutterRef.current) gutterRef.current.style.transform = `translateY(${-scrollTop}px)`;
  };

  return (
    <div
      className="code-editor relative flex min-h-0 flex-1 overflow-hidden font-mono text-[14px]"
      style={{ ['--line' as string]: `${LINE_HEIGHT}px`, ['--pad' as string]: `${PAD_Y}px` }}
    >
      <div className="relative w-12 shrink-0 overflow-hidden border-r border-border/70 bg-editor-gutter select-none">
        <div ref={gutterRef} className="absolute inset-x-0 top-0 pt-[var(--pad)]" aria-hidden>
          {Array.from({ length: lineCount }, (_, i) => (
            <div
              key={i}
              className={
                'h-[var(--line)] pr-3 text-right text-[12px] leading-[var(--line)] tabular-nums ' +
                (errorLine === i + 1 ? 'font-semibold text-destructive' : 'text-muted-foreground/70')
              }
            >
              {i + 1}
            </div>
          ))}
        </div>
      </div>

      <div className="relative min-w-0 flex-1 overflow-hidden">
        <pre
          ref={highlightRef}
          aria-hidden
          className="pointer-events-none absolute top-0 left-0 m-0 min-w-full px-4 py-[var(--pad)] leading-[var(--line)] whitespace-pre [tab-size:3]"
        >
          {errorLine !== null && (
            <span
              className="absolute inset-x-0 h-[var(--line)] bg-destructive/10"
              style={{ top: PAD_Y + (errorLine - 1) * LINE_HEIGHT }}
            />
          )}
          <span className="relative">
            <Highlighted source={text} tokens={tokens} />
            {'\n'}
          </span>
        </pre>
        <textarea
          aria-label="Sandscript code"
          aria-describedby="editor-help"
          className="absolute inset-0 h-full w-full resize-none overflow-auto bg-transparent px-4 py-[var(--pad)] leading-[var(--line)] whitespace-pre text-transparent caret-foreground outline-none [tab-size:3] selection:bg-sand/30"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={onKeyDown}
          onScroll={onScroll}
          autoCorrect="off"
          autoCapitalize="off"
          autoComplete="off"
          spellCheck={false}
          wrap="off"
        />
      </div>
      <p id="editor-help" className="sr-only">
        Press Control or Command plus Enter to run. Press Escape, then Tab, to leave the editor.
      </p>
    </div>
  );
}
/** End Code Generated by Claude on 2026-11-25 */
